class Chart{constructor(ctx,config){this.ctx=ctx.getContext("2d");this.config=config;this.draw()}destroy(){this.ctx.clearRect(0,0,this.ctx.canvas.width,this.ctx.canvas.height)}draw(){const c=this.ctx,cv=c.canvas,d=this.config.data.datasets[0].data||[],labels=this.config.data.labels||[];const w=cv.width=cv.clientWidth*devicePixelRatio,h=cv.height=cv.clientHeight*devicePixelRatio;c.scale(devicePixelRatio,devicePixelRatio);const W=cv.clientWidth,H=cv.clientHeight,p=32;c.clearRect(0,0,W,H);c.strokeStyle="#ddd";c.beginPath();c.moveTo(p,p);c.lineTo(p,H-p);c.lineTo(W-p,H-p);c.stroke();if(!d.length)return;const min=Math.min(...d),max=Math.max(...d),range=max-min||1;c.strokeStyle="#111";c.lineWidth=2;c.beginPath();d.forEach((v,i)=>{const x=p+(W-p*2)*(d.length===1?0.5:i/(d.length-1));const y=H-p-(H-p*2)*((v-min)/range);i?c.lineTo(x,y):c.moveTo(x,y);});c.stroke();c.fillStyle="#111";c.font="12px sans-serif";c.fillText("単価推移",p,18);c.fillStyle="#666";c.fillText("¥"+max.toLocaleString(),p+4,p+12);c.fillText("¥"+min.toLocaleString(),p+4,H-p-6);}}